import React from 'react';
import axios from 'axios';
import { jsPDF } from 'jspdf';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import { ClerkProvider, SignIn, SignUp, SignedIn, SignedOut, UserButton, useUser } from '@clerk/clerk-react';
import {
  Container, Paper, Typography, Button, Box, CircularProgress, Alert, TextField,
  AppBar, Toolbar, IconButton
} from '@mui/material';
import { CloudUpload } from '@mui/icons-material';
import MenuIcon from '@mui/icons-material/Menu';

const clerkFrontendApi = ProcessingInstruction.envpk_test_Y2xvc2luZy1iYXNpbGlzay00NS5jbGVyay5hY2NvdW50cy5kZXYk; // Store in .env

// File Analysis Component
function MalwareAnalysis() {
  const [selectedFile, setSelectedFile] = React.useState(null);
  const [analysisResult, setAnalysisResult] = React.useState(null);
  const [loading, setLoading] = React.useState(false);
  const [errorMsg, setErrorMsg] = React.useState('');
  const { user } = useUser();

  const handleFileChange = (e) => {
    setSelectedFile(e.target.files[0]);
    setAnalysisResult(null);
    setErrorMsg('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedFile) {
      setErrorMsg('Please select a file before analyzing.');
      return;
    }
    setLoading(true);
    setErrorMsg('');
    setAnalysisResult(null);

    const formData = new FormData();
    formData.append('file', selectedFile);

    try {
      const response = await axios.post('http://127.0.0.1:8000/analyze', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });
      setAnalysisResult(response.data);
    } catch (error) {
      console.error('Error in Axios request:', error);
      setErrorMsg(error.response?.data?.detail || 'Error analyzing file. Please try again.');
    }
    setLoading(false);
  };

  const downloadPDFReport = () => {
    if (!analysisResult) return;
    const doc = new jsPDF();
    doc.setFontSize(16);
    doc.text('Malware Analysis Report', 10, 20);
    doc.setFontSize(12);
    doc.text(`Filename: ${analysisResult.filename}`, 10, 30);
    doc.text(`File Type: ${analysisResult.file_type}`, 10, 40);

    if (analysisResult.file_type === 'exe') {
      doc.text(`Risk Factor: ${analysisResult.risk_factor}/100`, 10, 50);
      doc.text('YARA Analysis:', 10, 60);
      doc.text(`${analysisResult.risk_details?.yara || 'N/A'}`, 10, 70);
    } else if (analysisResult.file_type === 'pdf') {
      doc.text('PDF Analysis:', 10, 50);
      doc.text(`Number of Pages: ${analysisResult.pdf_info?.num_pages || 'N/A'}`, 10, 60);
    } else if (analysisResult.file_type === 'docx') {
      doc.text('Document Analysis:', 10, 50);
      doc.text(`Word Count: ${analysisResult.doc_info?.word_count || 'N/A'}`, 10, 60);
    }
    doc.save('analysis_report.pdf');
  };

  return (
    <Container maxWidth="md" sx={{ mt: 4 }}>
      <Typography variant="h4" gutterBottom>
        Malware Analysis Dashboard
      </Typography>
      <Typography variant="h6">Welcome, {user?.fullName}!</Typography>
      <UserButton />
      <Paper elevation={3} sx={{ p: 4, mt: 2 }}>
        <Typography variant="h5" align="center">Upload File for Analysis</Typography>
        <Box component="form" onSubmit={handleSubmit} sx={{ mt: 2 }}>
          <Button variant="contained" component="label" startIcon={<CloudUpload />} color="primary">
            Choose File
            <input type="file" hidden accept=".exe,.pdf,.doc,.docx" onChange={handleFileChange} />
          </Button>

          {selectedFile && (
            <TextField label="Selected File" variant="outlined" fullWidth value={selectedFile.name} InputProps={{ readOnly: true }} sx={{ mt: 2 }} />
          )}

          <Button variant="contained" color="secondary" type="submit" disabled={loading} sx={{ mt: 2 }}>
            {loading ? <CircularProgress size={24} /> : 'Analyze File'}
          </Button>
        </Box>

        {errorMsg && <Alert severity="error" sx={{ mt: 2 }}>{errorMsg}</Alert>}

        {analysisResult && (
          <Box sx={{ mt: 4 }}>
            <Typography variant="h5">Analysis Report</Typography>
            <Paper elevation={1} sx={{ p: 2, mt: 2 }}>
              <Typography variant="subtitle1">Filename: {analysisResult.filename}</Typography>
              <Typography variant="subtitle1">File Type: {analysisResult.file_type}</Typography>
              {analysisResult.file_type === 'exe' && <Typography variant="h6">Risk Factor: {analysisResult.risk_factor}/100</Typography>}
            </Paper>
            <Button variant="outlined" sx={{ mt: 2 }} onClick={downloadPDFReport}>Download PDF Report</Button>
          </Box>
        )}
      </Paper>
    </Container>
  );
}

// Home Page Component
function Home() {
  return (
    <Container maxWidth="md" sx={{ mt: 4 }}>
      <Typography variant="h4">Welcome to Malware Analysis</Typography>
      <SignedOut>
        <Typography variant="h6" color="error">Sign in to access analysis tools.</Typography>
        <Link to="/sign-in">
          <Button variant="contained" color="primary">Sign In</Button>
        </Link>
      </SignedOut>
      <SignedIn>
        <Typography variant="h6" color="success">You're signed in! 🎉</Typography>
        <Link to="/dashboard">
          <Button variant="contained" color="secondary" sx={{ ml: 2 }}>Go to Dashboard</Button>
        </Link>
      </SignedIn>
    </Container>
  );
}

// App Component with Routing
function App() {
  return (
    <ClerkProvider frontendApi={clerkFrontendApi}>
      <Router>
        {/* Navbar */}
        <AppBar position="static">
          <Toolbar>
            <IconButton edge="start" color="inherit" aria-label="menu">
              <MenuIcon />
            </IconButton>
            <Typography variant="h6" sx={{ flexGrow: 1 }}>
              <Link to="/" style={{ textDecoration: 'none', color: 'white' }}>Malware Analysis</Link>
            </Typography>
            <UserButton />
          </Toolbar>
        </AppBar>

        {/* Routes */}
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/sign-in" element={<SignIn />} />
          <Route path="/sign-up" element={<SignUp />} />
          <Route path="/dashboard" element={
            <SignedIn>
              <MalwareAnalysis />
            </SignedIn>
          } />
        </Routes>

        {/* Footer */}
        <footer style={{ marginTop: '16px', padding: '16px', textAlign: 'center', backgroundColor: '#f5f5f5' }}>
          <Typography variant="body2" color="textSecondary">
            © {new Date().getFullYear()} Malware Detection Service. All rights reserved.
          </Typography>
        </footer>
      </Router>
    </ClerkProvider>
  );
}

export default App;
